class Pipeline_operation_model extends CI_Model {
 public function __construct(){parent::__construct();$this->load->model('Pipeline_billing_model','billing');$this->load->model('Pipeline_master_model','masterdata');$this->load->model('Pipeline_spp_model','spp');$this->load->model('Pipeline_spp_invoice_model','spp_invoice');$this->load->library('Pipeline_operation_forms',array(), 'operation_forms');}
 private function ids(){return array_map('intval',array_column($this->billing->branches(),'SpbbID'));}
 public function rows($kind=null){$ids=$this->ids();if(!$ids)return array();$this->db->from('PipelineOperation');if($kind)$this->db->where('Kind',$kind);return $this->db->where_in('SpbbID',$ids)->order_by('OperationID','DESC')->get()->result_array();}
 public function row($id){foreach($this->rows() as $r)if((int)$r['OperationID']===(int)$id)return $r;return null;}
 public function bunker($id){$ids=$this->ids();if(!$ids)return null;return $this->db->where_in('SpbbID',$ids)->where('BunkerID',(int)$id)->get('PipelineBunker')->row_array();}
 public function tariffs(){ $ids=$this->ids();return $ids?$this->db->where_in('SpbbID',$ids)->order_by('EffectiveDate','DESC')->order_by('PassTariffID','DESC')->get('PipelinePassTariff')->result_array():array(); }
 public function source($kind,$captureId,$vesselId,$bunkerId,$parentId){
  foreach(array($captureId,$vesselId,$bunkerId,$parentId) as $sourceId)if(!is_scalar($sourceId)||!preg_match('/^\d+$/D',(string)$sourceId))throw new InvalidArgumentException('Pilihan sumber tidak valid.');
  $out=array('CaptureID'=>null,'BunkerID'=>null,'ParentID'=>null);$defaults=array();
  if($kind==='BASTB'){
   $capture=$this->spp->capture($captureId);$vessel=$this->masterdata->record('vessel',$vesselId);
   if($capture&&$this->spp->flow_request($capture))throw new RuntimeException('SPP sudah dipakai di Pesanan Pipanisasi.');
   if($capture&&($capture['DeliveryID']||$capture['DocumentID']))throw new RuntimeException('SPP sudah ditautkan ke alur DO lama, tidak dapat ditagihkan ulang melalui BASTB.');
   if(!$capture||!$vessel||(int)$capture['SpbbID']!==(int)$vessel['SpbbID']||!(int)$vessel['IsActive']||!(int)$vessel['CompanyActive'])throw new RuntimeException('Pilih SPP dan kapal aktif pada area yang sama.');
   $out+=array('SpbbID'=>(int)$vessel['SpbbID'],'VesselID'=>(int)$vessel['VesselID']);$out['CaptureID']=(int)$captureId;$reference=trim($capture['LONumber'])!==''?'LO:'.mb_strtoupper(trim($capture['LONumber'])):(trim($capture['ShipmentNo'])!==''?'SHIP:'.mb_strtoupper(trim($capture['ShipmentNo'])):'');if($reference==='')throw new RuntimeException('Lengkapi Nomor LO atau Shipment pada SPP sebelum membuat BASTB.');$out['SourceKey']=$reference;
   $defaults=array('VesselName'=>$vessel['VesselName'],'CompanyName'=>$vessel['CompanyName'],'VolumeLiters'=>$capture['OrderedLiters'],'FillingDate'=>substr((string)$capture['DeliveryDate'],0,10),'FillingTime'=>'','DepotExitTime'=>substr((string)$capture['DepotExitTime'],0,5),'FuelType'=>$capture['ProductName'],'Location'=>$capture['Destination'],'BillingCompany'=>$capture['Buyer'],'DriverName'=>$capture['DriverName'],'VehicleNumber'=>$capture['VehicleOrVessel']);
   if($bunkerId){$bunker=$this->bunker($bunkerId);if(!$bunker||(int)$bunker['VesselID']!==(int)$vesselId)throw new RuntimeException('Permohonan bunker harus milik kapal dan area yang sama.');$b=json_decode($bunker['Snapshot'],true);$out['BunkerID']=(int)$bunkerId;$defaults['Location']=$b['Position'];$defaults['Captain']=$b['Captain'];$defaults['BillingCompany']=$b['Supplier'];$defaults['Place']=$b['Place'];}
  }else{
   $parent=$this->row($parentId);if(!$parent||$parent['Kind']!=='BASTB')throw new RuntimeException('Pilih BASTB pada area Anda.');$defaults=json_decode($parent['Snapshot'],true);$out=array('SpbbID'=>(int)$parent['SpbbID'],'VesselID'=>(int)$parent['VesselID'],'CaptureID'=>$parent['CaptureID'],'BunkerID'=>$parent['BunkerID'],'ParentID'=>(int)$parentId);
   $capture=$this->spp->capture($parent['CaptureID']);if($capture){$defaults['DriverName']=$capture['DriverName'];$defaults['VehicleNumber']=$capture['VehicleOrVessel'];}
   $defaults['TransportCompany']=isset($defaults['BillingCompany'])?$defaults['BillingCompany']:$parent['CompanyName'];
  }
  unset($defaults['DocumentNo']);$defaults['DocumentDate']=!empty($defaults['FillingDate'])?$defaults['FillingDate']:date('Y-m-d');$defaults['PeopleCount']=2;$defaults['VehicleCount']=1;return array('links'=>$out,'fields'=>$defaults);
 }
 public function transaction($fn){$debug=$this->db->db_debug;$this->db->db_debug=false;$this->db->trans_begin();try{$q=$this->db->query("DECLARE @r int;EXEC @r=sp_getapplock @Resource='pipeline-operation-workflow',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000;SELECT @r AS r");if(!$q||(int)$q->row()->r<0)throw new RuntimeException('Dokumen sedang diproses, coba kembali.');$result=$fn();if(!$this->db->trans_status())throw new RuntimeException('Database menolak data. Periksa nomor dokumen yang duplikat.');$this->db->trans_commit();return $result;}catch(Throwable $e){$this->db->trans_rollback();throw $e;}finally{$this->db->db_debug=$debug;}}
 public function insert($table,$key,$data){$cols=array_map(function($c){return '['.$c.']';},array_keys($data));$q=$this->db->query('INSERT INTO '.$table.' ('.implode(',',$cols).') OUTPUT INSERTED.'.$key.' NewID VALUES ('.implode(',',array_fill(0,count($data),'?')).')',array_values($data),true);if(!$q){$failure=$this->db->error();log_message('error','Pipeline insert '.$table.' failed: '.json_encode($failure));if($table==='PipelineDelivery')throw new RuntimeException('DO tidak dapat disimpan. Periksa nomor DO, tanggal, dan angka volume atau totalizer. Kode pemeriksaan DO-SAVE.');throw new RuntimeException('Gagal menyimpan; periksa duplikasi nomor atau field.');}return (int)$q->row()->NewID;}
 public function audit($kind,$id,$action,$row){if(!$this->db->insert('PipelineDocumentAudit',array('Kind'=>$kind,'RecordID'=>$id,'Action'=>$action,'Snapshot'=>json_encode($row,JSON_UNESCAPED_UNICODE),'UserID'=>$this->session->userdata('MIS_LOGGED_ID'))))throw new RuntimeException('Audit gagal disimpan.');}
 public function mutable($row){if($this->db->where('OperationID',$row['OperationID'])->get('PipelineOperationInvoice')->row_array())throw new RuntimeException('Dokumen sudah ditagihkan. Revisi invoice terlebih dahulu.');if($this->db->where('ParentID',$row['OperationID'])->get('PipelineOperation')->row_array())throw new RuntimeException('Dokumen sudah dipakai oleh RDT/Pass. Revisi dokumen turunannya terlebih dahulu.');}
 public function save($kind,$post,$id=null){return $this->transaction(function()use($kind,$post,$id){
  $old=$id?$this->row($id):null;if($id&&(!$old||$old['Kind']!==$kind))throw new RuntimeException('Dokumen tidak ditemukan.');if($old){$this->mutable($old);if((string)$old['Version']!==(string)($post['Version']??''))throw new RuntimeException('Dokumen telah berubah. Muat ulang form.');$src=array('links'=>array_intersect_key($old,array_flip(array('SpbbID','VesselID','CaptureID','BunkerID','ParentID'))),'fields'=>json_decode($old['Snapshot'],true));}
  else $src=$this->source($kind,$post['CaptureID']??0,$post['VesselID']??0,$post['BunkerID']??0,$post['ParentID']??0);
  if(!$old&&$kind==='BASTB'&&$this->db->where('SpbbID',$src['links']['SpbbID'])->where('SourceKey',$src['links']['SourceKey'])->where('Kind','BASTB')->get('PipelineOperation')->row_array())throw new RuntimeException('Nomor LO / Shipment SPP sudah mempunyai BASTB, termasuk bila file diunggah ulang.');
  $capture=$this->spp->capture($src['links']['CaptureID']);if($kind==='BASTB'&&$capture&&trim($capture['LONumber'])!==''){$legacy=$this->db->select('P.DocumentID')->from('PipelineDocument P')->join('PipelineDelivery D','D.DeliveryID=P.DeliveryID')->where('D.SpbbID',$src['links']['SpbbID'])->where('P.DocumentType','SPP')->where('P.LoadingReference',trim($capture['LONumber']))->get()->row_array();if($legacy)throw new RuntimeException('SPP dengan LO ini sudah berada pada alur dokumen DO lama.');}if(!$capture||$capture['Status']!=='CONFIRMED')throw new RuntimeException('Konfirmasi hasil SPP terlebih dahulu sebelum membuat berita acara.');
  foreach(array('VesselName','CompanyName') as $key)$post[$key]=$src['fields'][$key];if($kind!=='BASTB')$post['BillingCompany']=$src['fields']['BillingCompany'];
  if(empty($post['DocumentNo'])){if($old)$post['DocumentNo']=$old['DocumentNo'];else{$max=$this->db->select_max('OperationID')->get('PipelineOperation')->row_array();$post['DocumentNo']=$kind.'/'.str_pad((string)((int)$max['OperationID']+1),4,'0',STR_PAD_LEFT).'/'.$src['links']['SpbbID'].'/'.date('Y');}}
  $data=$this->operation_forms->validate($kind,$post);$data+=array_intersect_key($src['fields'],array_flip(array('Captain','DriverName','VehicleNumber','DepotExitTime')));if($kind==='BASTB'){$billing=trim((string)($post['BillingCompany']??''));if($billing===''||mb_strlen($billing)>200)throw new RuntimeException('Perusahaan penagihan wajib diisi.');$data['BillingCompany']=$billing;}else $data['BillingCompany']=$src['fields']['BillingCompany'];
  if($kind==='RDT'&&abs($data['VolumeLiters']-(float)$src['fields']['VolumeLiters'])>0.001)throw new RuntimeException('Volume RDT harus sama dengan BASTB.');
  if($kind==='PASS'){$tariff=null;foreach($this->tariffs() as $t)if((int)$t['SpbbID']===(int)$src['links']['SpbbID']&&$t['VehicleType']===$data['VehicleType']&&substr($t['EffectiveDate'],0,10)<=$data['DocumentDate']){$tariff=$t;break;}if(!$tariff)throw new RuntimeException('Tarif jenis kendaraan belum berlaku pada tanggal pass. Isi Basic Tarif Pass terlebih dahulu.');$data['Tariff']=$tariff;$data['PassTotal']=round($data['PeopleCount']*$tariff['PersonRate']+$data['VehicleCount']*($tariff['VehicleRate']+$tariff['BerthRate']),2);}
  $row=$src['links']+array('Kind'=>$kind,'DocumentNo'=>$data['DocumentNo'],'DocumentDate'=>$data['DocumentDate'],'MovementDate'=>$kind==='PASS'?$data['DocumentDate']:$data['FillingDate'],'CompanyName'=>$data['BillingCompany'],'VolumeLiters'=>$data['VolumeLiters']??0,'TotalAmount'=>$data['PassTotal']??0,'Snapshot'=>json_encode($data,JSON_UNESCAPED_UNICODE));
  if($old){$this->audit($kind,$id,'EDIT',$old);$row['Version']=$old['Version']+1;if(!$this->db->where('OperationID',$id)->update('PipelineOperation',$row))throw new RuntimeException('Perubahan gagal disimpan.');return $id;}
  $row['CreatedBy']=$this->session->userdata('MIS_LOGGED_ID');$id=$this->insert('PipelineOperation','OperationID',$row);$this->audit($kind,$id,'CREATE',$row);return $id;
 });}
 public function remove($id){return $this->transaction(function()use($id){$r=$this->row($id);if(!$r)throw new RuntimeException('Dokumen tidak ditemukan.');$this->mutable($r);$this->audit($r['Kind'],$id,'DELETE',$r);$this->db->where('OperationID',$id)->delete('PipelineOperation');});}
 public function quote($ids,$editingInvoice=null,$captureIds=array()){
  if((!$ids&&!$captureIds)||count($ids)>500||count($ids)!==count(array_unique($ids)))throw new RuntimeException('Pilih dokumen yang unik.');$lines=array();$links=array();$branch=null;$company=null;$dates=array();$liters=0;$subtotal=0;$tax=0;
    $direct=$this->spp_invoice->quote($captureIds,$editingInvoice);if($captureIds){$branch=$direct['branch'];$company=$direct['company'];$dates=$direct['dates'];$liters=$direct['liters'];$subtotal=$direct['subtotal'];$tax=$direct['tax'];$lines=$direct['lines'];}
    foreach($ids as $id){$r=$this->row($id);if(!$r||!in_array($r['Kind'],array('BASTB','PASS'),true))throw new RuntimeException('Dokumen terpilih tidak valid.');if($branch!==null&&($branch!==(int)$r['SpbbID']||$company!==$r['CompanyName']))throw new RuntimeException('Dokumen harus satu area dan perusahaan penagihan.');$branch=(int)$r['SpbbID'];$company=$r['CompanyName'];$dates[]=$r['DocumentDate'];$links[$r['OperationID']]=$r;
   $s=json_decode($r['Snapshot'],true);if($r['Kind']==='BASTB'){
     $sourceCapture=$this->spp->capture($r['CaptureID']);if($sourceCapture)$this->spp_invoice->available($sourceCapture,$editingInvoice);
     if($this->db->where('SpbbID',$r['SpbbID'])->where('SourceKey',$r['SourceKey'])->get('PipelineSppInvoice')->row_array())throw new RuntimeException('SPP sudah ditagihkan langsung.');
     foreach($direct['links'] as $d){$same=(int)$d['CaptureID']===(int)$r['CaptureID']||$d['SourceKey']===$r['SourceKey'];$ds=json_decode($d['Snapshot'],true);foreach(array('LONumber','ShipmentNo') as $col)if($sourceCapture&&trim((string)$sourceCapture[$col])!==''&&mb_strtoupper(trim($sourceCapture[$col]))===mb_strtoupper(trim((string)$ds[$col])))$same=true;if($same)throw new RuntimeException('Pilih SPP atau BASTB untuk sumber yang sama, jangan keduanya.');}$rdt=$this->db->where('ParentID',$r['OperationID'])->where('Kind','RDT')->get('PipelineOperation')->row_array();if(!$rdt)throw new RuntimeException('BASTB '.$r['DocumentNo'].' belum memiliki RDT.');$links[$rdt['OperationID']]=$rdt;$q=(float)$rdt['VolumeLiters'];$liters+=$q;$rate=$this->billing->rate('FUEL_ADMIN',substr($r['DocumentDate'],0,10),$branch);$vat=$this->billing->rate('VAT',substr($r['DocumentDate'],0,10),$branch);$qty=$this->pipeline_finance->spp_quantity($rdt['VolumeLiters'],$rate['Unit'],$sourceCapture['DensityObs']??null);$amount=$this->pipeline_finance->amount($qty,$rate['Amount']);$lines[]=array('ServiceCode'=>'FUEL_ADMIN','Description'=>$rate['ServiceName'].' — '.$r['DocumentNo'],'Quantity'=>$qty,'Unit'=>$rate['Unit'],'Rate'=>$rate['Amount'],'RateID'=>$rate['RateID'],'Amount'=>$amount);$vatAmount=$this->pipeline_finance->amount($amount/100,$vat['Amount']);$lines[]=array('ServiceCode'=>'VAT','Description'=>'PPN Jasa Administrasi BBM','Quantity'=>$amount,'Unit'=>'Dasar Rp','Rate'=>$vat['Amount'],'RateID'=>$vat['RateID'],'Amount'=>$vatAmount);$subtotal+=$amount;$tax+=$vatAmount;
   }else{foreach(array(array('PersonRate','PeopleCount','Pas Masuk Orang Dewasa','Orang'),array('VehicleRate','VehicleCount','Pas Masuk '.$s['VehicleType'],'Unit'),array('BerthRate','VehicleCount','Jasa Dermaga '.$s['VehicleType'],'Unit')) as $n=>$fee){$amt=$this->pipeline_finance->amount($s[$fee[1]],$s['Tariff'][$fee[0]]);$lines[]=array('ServiceCode'=>'PASS_VISIT','Description'=>$fee[2].' — '.$r['DocumentNo'],'Quantity'=>$s[$fee[1]],'Unit'=>$fee[3],'Rate'=>$s['Tariff'][$fee[0]],'RateID'=>null,'Amount'=>$amt);$subtotal+=$amt;}}
  }
  foreach($links as $id=>$r){$billed=$this->db->where('OperationID',$id)->get('PipelineOperationInvoice')->row_array();if($billed&&(!$editingInvoice||(int)$billed['InvoiceID']!==(int)$editingInvoice))throw new RuntimeException('Dokumen '.$r['DocumentNo'].' sudah ditagihkan.');}
  if($subtotal+$tax<=0)throw new RuntimeException('Tidak ada nilai tagihan.');$sorted=array();foreach(array('PASS_VISIT','FUEL_ADMIN','VAT') as $code)foreach($lines as $line)if($line['ServiceCode']===$code)$sorted[]=$line;$lines=$sorted;sort($dates);return array('SpbbID'=>$branch,'CustomerName'=>$company,'PeriodStart'=>substr(reset($dates),0,10),'PeriodEnd'=>substr(end($dates),0,10),'lines'=>$lines,'links'=>$links,'spp_links'=>$direct['links'],'TotalLiters'=>$liters,'TotalTons'=>$liters/1000,'Subtotal'=>$subtotal,'Tax'=>$tax,'GrandTotal'=>$subtotal+$tax,'InvoiceRevision'=>$editingInvoice?hash('sha256',json_encode($this->billing->invoice($editingInvoice))):null);
 }
 public function invoice_create($ids,$input,$expected,$editId=null,$captureIds=array()){return $this->transaction(function()use($ids,$input,$expected,$editId,$captureIds){
  $old=null;if($editId){$old=$this->billing->invoice($editId);if(!$old||$old['InvoiceType']!=='INVOICE')throw new RuntimeException('Invoice tidak ditemukan.');$lock=$this->db->query("DECLARE @r int;EXEC @r=sp_getapplock @Resource=?,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000;SELECT @r r",array('pipeline-'.hash('sha256','payment/'.$editId)));if(!$lock||(int)$lock->row()->r<0)throw new RuntimeException('Invoice sedang diproses.');if($this->db->where('InvoiceID',$editId)->get('PipelinePayment')->row_array())throw new RuntimeException('Invoice sudah dibayar; rincian tidak dapat direvisi.');if(!$this->db->where('InvoiceID',$editId)->get('PipelineOperationInvoice')->row_array()&&!$this->db->where('InvoiceID',$editId)->get('PipelineSppInvoice')->row_array())throw new RuntimeException('Rincian invoice alur lama tidak dapat diganti dengan alur berita acara.');if($this->db->where('InvoiceID',$editId)->get('PipelineInvoiceDelivery')->row_array())throw new RuntimeException('Invoice DO lama tidak dapat diganti dengan alur berita acara.');}
  $quote=$this->quote($ids,$editId,$captureIds);if($old&&((int)$old['SpbbID']!==(int)$quote['SpbbID']||$old['CustomerID']!==$this->pipeline_finance->company_key($quote['CustomerName'])))throw new RuntimeException('Revisi invoice harus tetap pada area dan perusahaan penagihan yang sama.');if($input['InvoiceDate']<$quote['PeriodEnd'])throw new RuntimeException('Tanggal invoice tidak boleh sebelum akhir periode dokumen.');if(!hash_equals($expected,hash('sha256',json_encode($quote))))throw new RuntimeException('Data berubah. Preview kembali.');$header=array_intersect_key($quote,array_flip(array('SpbbID','CustomerName','PeriodStart','PeriodEnd','TotalLiters','TotalTons','Subtotal','Tax','GrandTotal')));$header+=array('CustomerID'=>$this->pipeline_finance->company_key($quote['CustomerName']),'InvoiceNumber'=>$input['InvoiceNumber'],'InvoiceDate'=>$input['InvoiceDate'],'DueDate'=>$input['DueDate'],'ConversionMode'=>'LITER_1000','InvoiceType'=>'INVOICE','CreatedBy'=>$this->session->userdata('MIS_LOGGED_ID'));
  foreach($this->billing->branches() as $branch)if((int)$branch['SpbbID']===(int)$header['SpbbID']){$header['IssuerName']=$branch['SpbbName'];$header['Place']=$branch['Area'];}
  $header+=array('Signatory'=>$input['Signatory']??'','SignatoryTitle'=>$input['SignatoryTitle']??'AN. GENERAL MANAGER, DEPARTEMENT HEAD BISNIS DAN PELAYANAN','Subject'=>'Tagihan Penggunaan Fasilitas Bunker','CustomerAddress'=>'','Notes'=>mb_substr('Dokumen: '.implode('; ',array_map(function($r){return $r['Kind'].' '.$r['DocumentNo'];},$quote['links'])).'; SPP: '.implode('; ',array_map(function($r){return $r['SourceKey'];},$quote['spp_links'])),0,1000));
  if($old){$this->audit('invoice',$editId,'EDIT',array('invoice'=>$old,'lines'=>$this->billing->lines($editId)));$id=$editId;$header['CreatedBy']=$old['CreatedBy'];if(!$this->db->where('InvoiceID',$id)->update('PipelineInvoice',$header))throw new RuntimeException('Revisi invoice gagal.');foreach(array('PipelineSppInvoice','PipelineOperationInvoice','PipelineInvoiceLine') as $t)$this->db->where('InvoiceID',$id)->delete($t);}else $id=$this->insert('PipelineInvoice','InvoiceID',$header);foreach($quote['lines'] as $line){$line['InvoiceID']=$id;if(!$this->db->insert('PipelineInvoiceLine',$line))throw new RuntimeException('Rincian invoice gagal disimpan.');}foreach($quote['links'] as $r)if(!$this->db->insert('PipelineOperationInvoice',array('OperationID'=>$r['OperationID'],'InvoiceID'=>$id)))throw new RuntimeException('Dokumen sudah ditagihkan proses lain.');foreach($quote['spp_links'] as $link){$link['InvoiceID']=$id;if(!$this->db->insert('PipelineSppInvoice',$link))throw new RuntimeException('SPP sudah ditagihkan proses lain.');}$this->audit('invoice',$id,$old?'EDIT':'CREATE',$header);return $id;
 });}
